def rule_address_principal_offices(doc: dict) -> list[dict]:
    '''Cover-page address: spans within a small window around "(Address of principal executive offices)" or "(Zip Code)" labels on page 1.'''
    texts = doc.get("texts", [])
    keep = set()
    n = len(texts)
    for i, span in enumerate(texts):
        if span.get("page_no") != 1:
            continue
        t = (span.get("text") or "").lower()
        is_addr_label = ("address" in t) and ("principal executive offices" in t)
        is_zip_label = "(zip code)" in t
        if is_addr_label or is_zip_label:
            lo = max(0, i - 5)
            hi = min(n, i + 2)
            for j in range(lo, hi):
                if texts[j].get("page_no") == 1:
                    keep.add(j)
    return [texts[j] for j in sorted(keep)]

def rule_page1_address_or_zip_neighbors(doc: dict) -> list[dict]:
    """Return spans adjacent to page-1 address/ZIP label spans."""
    try:
        spans = doc.get("texts", [])
        idxs = set()
        for i, span in enumerate(spans):
            if span.get("page_no") != 1:
                continue
            txt = ((span.get("text") or "") + " " + (span.get("text_span") or "")).lower()
            if (
                "address of principal executive offices" in txt
                or "address and telephone number, including area code, of registrant" in txt
                or "address of principal executive offices and zip code" in txt
                or "(zip code)" in txt
            ):
                for j in range(max(0, i - 2), min(len(spans), i + 3)):
                    if spans[j].get("page_no") == 1:
                        idxs.add(j)
        return [spans[i] for i in sorted(idxs)]
    except Exception:
        return []

def rule_cover_principal_offices_page1(doc: dict) -> list[dict]:
    """Retrieve page-1 cover spans containing the principal executive office address or its immediate label."""
    try:
        import re
        out = []
        for span in doc.get("texts", []):
            text = (span.get("text") or "")
            if span.get("page_no") != 1:
                continue
            if span.get("label") not in {"text", "section_header"}:
                continue
            low = text.lower()
            path = ((span.get("structure") or {}).get("path_text") or "").lower()
            if "address of principal executive offices" in low or "address of principal executive offices" in path:
                out.append(span)
                continue
            if "address and telephone number" in low and "principal executive offices" in low:
                out.append(span)
                continue
            if "address of principal executive offices and zip code" in low:
                out.append(span)
                continue
            if "zip code" in low and ("principal executive offices" in low or "address of principal executive offices" in path):
                out.append(span)
                continue
            if re.search(r'\b\d{1,5}\s+[A-Za-z0-9.&\- ]{3,},\s*[A-Za-z .\-]+\s+\d{5}(?:-\d{4})?\b', text):
                out.append(span)
                continue
            if re.search(r'\b(?:one|two|three|four|five|six|seven|eight|nine|ten)\s+[A-Za-z0-9.&\- ]+,\s*[A-Za-z .\-]+\s+\d{5}(?:-\d{4})?\b', low):
                out.append(span)
                continue
        return out
    except Exception:
        return []

