def rule_principal_offices_narrative_location(doc: dict) -> list[dict]:
    """Return narrative sentences that explicitly state where the principal executive offices are located."""
    try:
        full_text = " ".join((doc.get("text") or "").split())
        if not full_text:
            return []

        phrases = (
            "our principal executive offices are located at",
            "our principal executive offices are located in",
            "principal executive offices are located at",
            "principal executive offices are located in",
            "principal executive offices and main research facilities",
            "principal executive offices are",
        )

        low = full_text.lower()
        if "principal executive offices" not in low:
            return []
        if not any(p in low for p in phrases):
            return []
        if "located" not in low and "main research facilities" not in low:
            return []

        m = re.search(
            r"principal executive offices.*?located\s+(?:at|in(?: the)?)\s+(.+?)(?:,?\s+and\b|(?:\.\s)|$)",
            full_text,
            flags=re.IGNORECASE,
        )
        if not m:
            return []

        combined = m.group(1).strip()
        combined = re.sub(r"^\bthe\s+", "", combined, flags=re.IGNORECASE)
        combined = re.sub(r"\bmetropolitan area\.?$", "", combined, flags=re.IGNORECASE).strip(" ,")
        combined = " ".join(combined.split())
        if not combined:
            return []

        out = {"text": combined}
        if doc.get("pages"):
            out["page_no"] = doc["pages"][0].get("page_no")
        return [out]

        return []
    except Exception:
        return []

def rule_principal_offices_cover_window(doc: dict) -> list[dict]:
    """Return the first-page cover-page block around the principal executive offices address label."""
    try:
        import re

        records = (
            doc.get("lines")
            or doc.get("paragraphs")
            or doc.get("pages")
            or doc.get("texts")
            or []
        )
        if not records:
            return []

        def _page_num(item: dict):
            page = item.get("page_no")
            try:
                return int(page)
            except Exception:
                return page if page is not None else 10**9

        def _ord_num(item: dict):
            for key in ("line_no", "paragraph_no", "page_no"):
                val = item.get(key)
                try:
                    return int(val)
                except Exception:
                    continue
            return 10**9

        ordered = sorted(enumerate(records), key=lambda pair: (_page_num(pair[1]), _ord_num(pair[1]), pair[0]))

        numeric_pages = [p for _, item in ordered if isinstance((p := _page_num(item)), int)]
        first_page = min(numeric_pages) if numeric_pages else 1

        def _text(item: dict) -> str:
            return " ".join(
                str(item.get(key) or "")
                for key in ("text", "text_span")
                if item.get(key)
            ).strip()

        def _is_match(text: str) -> bool:
            low = text.lower()
            if "address of principal executive offices" in low:
                return True
            if "address and telephone number" in low and "principal executive offices" in low:
                return True
            if "address of principal executive offices and zip code" in low:
                return True
            if "zip code" in low and "principal executive offices" in low:
                return True
            if re.search(
                r"\b\d{1,6}\s+[A-Za-z0-9][A-Za-z0-9&'().,\-\/ ]{3,},\s*[A-Za-z .'\-]+(?:\s+\d{5}(?:-\d{4})?)?\b",
                text,
            ):
                return True
            if re.search(
                r"\b(?:one|two|three|four|five|six|seven|eight|nine|ten)\s+[A-Za-z0-9][A-Za-z0-9&'().,\-\/ ]{3,},\s*[A-Za-z .'\-]+(?:\s+\d{5}(?:-\d{4})?)?\b",
                low,
            ):
                return True
            return False

        def _is_candidate_line(text: str) -> bool:
            if not text:
                return False
            low = text.lower()
            if "address" in low or "telephone" in low or "zip code" in low:
                return False
            if re.search(
                r"\b\d{1,6}\s+[A-Za-z0-9][A-Za-z0-9&'().,\-\/ ]{2,},\s*[A-Za-z .'\-]+(?:,\s*[A-Za-z .'\-]+)?(?:\s+\d{5}(?:-\d{4})?)?\b",
                text,
            ):
                return True
            if re.search(
                r"\b[A-Z][A-Za-z .'\-]+,\s*(?:[A-Z]{2}|[A-Za-z][A-Za-z .'\-]+)(?:\s+\d{5}(?:-\d{4})?)?(?:,\s*[A-Za-z][A-Za-z .'\-]+)?\b",
                text,
            ):
                return True
            if re.search(r"\b[A-Z][A-Za-z .'\-]+\s+[A-Z]{2}\b", text):
                return True
            return False

        anchor = None
        for idx, item in ordered:
            if _page_num(item) != first_page:
                continue
            text = _text(item)
            low = text.lower()
            if (
                "address of principal executive offices" in low
                or "address and telephone number" in low and "principal executive offices" in low
                or "address of principal executive offices and zip code" in low
                or ("zip code" in low and "principal executive offices" in low)
            ):
                anchor = idx
                break

        if anchor is None:
            for idx, item in ordered:
                if _page_num(item) != first_page:
                    continue
                text = _text(item)
                if text and _is_candidate_line(text):
                    anchor = idx
                    break

        if anchor is None:
            return []

        start = max(0, anchor - 4)
        end = min(len(ordered), anchor + 3)
        keep = []
        fallback = []
        for j in range(start, end):
            if _page_num(ordered[j][1]) != first_page:
                continue
            idx, item = ordered[j]
            text = _text(item)
            fallback.append(idx)
            if _is_candidate_line(text):
                keep.append(idx)

        if not keep:
            keep = fallback

        if not keep:
            return []

        parts = []
        for i in keep:
            txt = _text(records[i])
            if txt:
                low = txt.lower()
                if "address of principal executive offices" in low:
                    continue
                if "zip code" in low or "telephone" in low:
                    continue
                parts.append(" ".join(txt.split()).strip(" ,;"))
        combined = ", ".join(parts).strip()
        if not combined:
            return []

        anchor_item = records[keep[0]]
        out = {"text": combined}
        for key in ("page_no", "line_no", "paragraph_no"):
            if anchor_item.get(key) is not None:
                out[key] = anchor_item.get(key)
        return [out]
    except Exception:
        return []

def rule_principal_offices_press_release_dateline(doc: dict) -> list[dict]:
    """Return the press-release dateline when the filing is a first-page 8-K/news release style document."""
    try:
        import re

        full_text = " ".join((doc.get("text") or "").split())
        if not full_text:
            return []

        dateline_re = re.compile(
            r"^\s*[A-Z][A-Za-z .&'\-]+,\s*[A-Z][a-z]{1,3}\.?,\s*[A-Z][a-z]+\.?\s+\d{1,2},\s+\d{4}\b"
        )

        m = dateline_re.search(full_text)
        if m:
            return [{"text": " ".join(m.group(0).split())}]

        return []
    except Exception:
        return []
